# -*- coding: utf-8 -*-
import json, re, glob
HQ = '/tmp/claude-0/-home-user-Pruebas/978f574d-1019-54bc-bb45-9f4fddd102bb/scratchpad/hq'
D = {}
for p in glob.glob(HQ + '/H*/passages.json'):
    d = json.load(open(p, encoding='utf8'))
    if isinstance(d, dict): d = d.get('items') or list(d.values())[0]
    for r in d:
        if isinstance(r, dict) and 'id' in r: D[r['id']] = r
def _cut(t, a, b):
    if a:
        if a in t: t = t[t.index(a):]
        else: print('WARN start', a)
    if b:
        if b in t: t = t[:t.index(b) + len(b)]
        else: print('WARN end', b)
    return t
def clean(t): return re.sub(r'\s+', ' ', t).strip()
def G(i, a=None, b=None): return clean(_cut(D[i]['greek'], a, b))
def EN(i, a=None, b=None): return clean(_cut(D[i]['english'], a, b))
LAG = 'Griego: Lagarde 1858 (escaneo con capa de texto); lo leyó un investigador en la imagen y lo comprobé en la p. 52 (captura HP20)'
LAGR = 'Griego: Lagarde 1858, leído por un investigador en la imagen de la página'
MIL = 'Griego: Miller (Oxford 1851), leído por un investigador en la imagen; sin cotejar con Wendland/Marcovich'
DUN = 'Griego: Duncker-Schneidewin 1859, leído por un investigador en la imagen (escaneo sin capa de texto)'
SAL = 'Inglés: Salmond, ANF vol. 5'
MAC = 'Inglés: MacMahon, ANF vol. 5'
def Q(i, lang, txt, es, ref, src): return dict(id=i, lang=lang, txt=txt, es=es, ref=ref, src=src)
S = []
def add(id, title, sub, quotes, res): S.append(dict(id=id, title=title, sub=sub, quotes=quotes, res=res))

add('HP01', 'Quién es Hipólito y qué conservamos de él', 'Un presbítero de Roma «de otra iglesia» (Eusebio), con el problema de la identidad sin resolver',
 [Q('H8-01','en',EN('H8-01'),'Igualmente Hipólito, que presidió otra iglesia en alguna parte, ha dejado escritos.','Eusebio, Historia eclesiástica 6.20.2','Inglés: McGiffert, NPNF2 vol. 1'),
  Q('H10-20','en',EN('H10-20'),'Hipólito, obispo de alguna iglesia (no he podido averiguar el nombre de la ciudad), escribió un cómputo de la Pascua y tablas cronológicas…','Jerónimo, De viris illustribus 61','Inglés: Richardson, NPNF2 vol. 3'),
  Q('H8-08','en',EN('H8-08'),'Leí el tratado de Hipólito, discípulo de Ireneo, titulado Contra las treinta y dos herejías. Empieza por los dositeanos y baja hasta las herejías de Noeto y los noetianos, que dice fueron refutadas por Ireneo en sus lecciones, de las cuales la presente obra es un resumen.','Focio, Biblioteca cód. 121','Inglés: Freese 1920; el francés de Henry lo vi en la p. 90 del PDF (solo imagen, leído con tesseract)')],
 '<b>Qué conservamos.</b> <i>Contra Noeto</i> (griego, 18 capítulos), la <i>Refutación de todas las herejías</i> (libros 1 y 4-10; el libro 9 trata de Noeto y Calixto y el 10.32-34 es su propia confesión), <i>Comentario a Daniel</i>, <i>Cristo y Anticristo</i> y fragmentos. <b>Límites.</b> Eusebio y Jerónimo <b>no dicen de qué ciudad era obispo</b>; la noticia de Focio («discípulo de Ireneo») la discuten los estudiosos; el «problema de Hipólito» (¿uno o dos autores?) no lo resolví: sólo cito a Cerrato/Schaff de segunda mano. Esta diapositiva no contiene doctrina trinitaria: sólo dice qué obras hay.')

add('HP02', 'Contra quién escribe: Noeto («Cristo es el Padre mismo») y la fórmula «el Padre se hizo su propio Hijo»', 'El adversario fija los términos de todo lo demás',
 [Q('H1-01','gr',G('H1-01', 'ἔφη τὸν χριστὸν'),'Dijo que Cristo era el Padre mismo, y que el Padre mismo había sido engendrado, y había padecido y muerto.','Contra Noeto 1','Lagarde 1858 p. 43; '+SAL+', p. 545'),
  Q('H1-03','gr',G('H1-03'),'¿Qué mal hago, pues, glorificando a Cristo? A lo cual responden los presbíteros: También nosotros sabemos de verdad que hay un solo Dios; conocemos a Cristo; conocemos al Hijo, que padeció como padeció, murió como murió, y resucitó al tercer día, y está a la derecha del Padre, y viene a juzgar a vivos y muertos. Y decimos esto que hemos aprendido.','Contra Noeto 1','Lagarde 1858 p. 43; '+SAL),
  Q('H3-05','gr',G('H3-05', 'Ὅτε μὲν'),'Cuando, pues, el Padre no había sido engendrado, con razón se le llamaba Padre; pero cuando se dignó someterse a la generación, engendrado, el Hijo se hizo él mismo su propio Hijo, no de otro.','Refutación IX.10','Duncker-Schneidewin p. 448-450; '+MAC+'. El «dice» no tiene sujeto expreso: Heráclito o Noeto (sin resolver)')],
 '<b>Qué muestra.</b> Hipólito no escribe contra un «trinitarismo» abstracto sino contra el <b>monarquianismo modalista</b>: un solo sujeto, Padre = Hijo. Los presbíteros que cita conocen <b>un solo Dios</b>, a <b>Cristo</b> y al <b>Hijo que padeció</b>, distinto del Padre que está «a la derecha del Padre» (lo dice el texto, no yo). <b>Límite.</b> Es un relato partidista de un adversario; no dice nada todavía del Espíritu.')

add('HP03', 'Contra Noeto 7-8: «uno en poder, dos personas», y «estos son verdaderamente tres»', 'Jn 10:30 («somos uno») leído por Hipólito',
 [Q('H1-20','gr',G('H1-20'),'Y si dice: él mismo dijo «yo y el Padre somos uno», atienda a esto y aprenda que no dijo «yo y el Padre soy uno», sino «somos uno». Pues el «somos» no se dice de uno solo, sino que mostró dos personas (prosopa), y un solo poder.','Contra Noeto 7','Lagarde 1858 p. 48-49; '+SAL+', p. 550. Lagarde imprime ἐπεί; el códice trae ἐπί'),
  Q('H1-24','gr',G('H1-24'),'Y hay muchos otros pasajes, mejor dicho, todos, que dan testimonio de la verdad. Tiene, pues, necesidad, aun sin quererlo, de confesar al Padre Dios omnipotente y a Cristo Jesús, Hijo de Dios, Dios hecho hombre, a quien el Padre sometió todo, salvo sí mismo y el Espíritu Santo, y que éstos son verdaderamente tres.','Contra Noeto 8','Lagarde 1858 p. 49-50; '+SAL+', p. 551'),
  Q('H1-25','gr',G('H1-25'),'Y si quiere saber cómo se demuestra que Dios es uno, sepa que el poder de éste es uno: en cuanto al poder, es un solo Dios; pero en cuanto a la economía, la manifestación es triple, como se demostrará después, cuando demos razón de la verdad.','Contra Noeto 8','Lagarde 1858 p. 50; '+SAL+', p. 551')],
 '<b>Qué dice.</b> «Dos personas (<i>prosopa</i>) y un solo poder» y «tres» (<i>tría</i>) con el Espíritu nombrado. <b>Límite que debo decir.</b> La unidad se dice <b>«en poder»</b> (<i>dýnamis</i>), no «en esencia»; y <i>prosopon</i> aquí no es todavía la «persona» de Basilio y Gregorio (Kelly, Hanson, Prestige, citados por un investigador, no leídos por mí). Aun así, el texto <b>distingue dos sujetos</b> y rechaza que «Hijo» y «Padre» sean uno solo. Un investigador anotó que el griego de ch. 7 tiene una variante textual abierta (H1-13: «λόγος σὰρξ ἦν» en Lagarde frente a «Λόγος γὰρ ἦν» en la nota de Migne): no la resolví.')

add('HP04', 'Contra Noeto 10-11: Dios «solo», sin nada contemporáneo; el Verbo «luz de luz», «otro» pero no otro Dios', 'La generación del Verbo como salida desde el Padre para crear',
 [Q('H2-03','gr',G('H2-03'),'Y como autor, consejero y artífice de lo que se iba haciendo, engendró el Verbo, al cual Verbo, teniéndolo en sí mismo invisible para el mundo creado, lo hace visible, pronunciando primero la voz, y engendrándolo como luz de luz, lo envió a la creación como Señor, su propia mente; el que antes era visible sólo para él, e invisible para el mundo que se hace, lo hace visible, para que el mundo, viéndolo en su manifestación, pudiera ser salvado.','Contra Noeto 10','Lagarde 1858 p. 51 (capturada en HP21); '+SAL+', p. 553'),
  Q('H2-04','gr',G('H2-04'),'Y así se presentó junto a él otro. Pero al decir «otro» no digo dos dioses, sino como luz de luz, o como agua de la fuente, o como rayo del sol. Pues el poder es uno, el que procede del todo, y el todo es el Padre, de quien procede el poder, el Verbo. Éste es la mente que, avanzando en el mundo, se mostraba como hijo de Dios. Todo, pues, por medio de él, y él solo «del Padre».','Contra Noeto 11','Lagarde 1858 p. 51 (capturada en HP21); '+SAL+', p. 554')],
 '<b>Por qué es difícil.</b> «Lo engendró… como autor y consejero de lo que se iba haciendo», «lo envió a la creación» y «se presentó otro» suenan a un Verbo que <b>comienza</b> con la creación; «poder» (<i>dýnamis</i>) y «del Padre» son las palabras que usa un unitario. <b>Resolución.</b> Las imágenes «luz de luz», «agua de la fuente» y «rayo del sol» son las imágenes que Atanasio, Gregorio y el Credo usarán para decir que el Hijo es <b>de la misma naturaleza</b> y que no hay «dos dioses» (Hipólito lo dice: «no digo dos dioses»). Newman (<i>Arians</i>, p. 195) cita el mismo pasaje y subraya que fueron defensas del Hijo, pero abiertas a mala lectura. <b>Límite.</b> El mismo texto dice que tenía «en sí» al Verbo (<i>ἔχων ἐν ἑαυτῷ</i>) antes de pronunciarlo; no dice cuánto tiempo, ni si «otro» antes de crear. El «Dios de Dios» del Credo no aparece en el texto de Hipólito que leí.')

add('HP05', 'Contra Noeto 14: «un solo Dios… dos personas, y la tercera la gracia del Espíritu Santo»', 'La frase más trinitaria de Hipólito, con su vocabulario propio',
 [Q('H2-07','gr',G('H2-07', 'ταῦτα μὲν οὖν', 'τὸ δὲ τρίτον τὸ ἅγιον πνεῦμα') if False else G('H2-07'),'Esto, pues, hermanos, lo indican las Escrituras; esta economía nos transmite también el bienaventurado Juan en el evangelio, dando testimonio y confesando Dios a este Verbo: «En el principio era el Verbo, y el Verbo estaba con Dios, y el Verbo era Dios». Si, pues, el Verbo, estando con Dios, es Dios, ¿qué dirá alguien? ¿Dices dos dioses? No diré dos dioses, sino uno; sí dos personas (prosopa), y, por economía, la tercera, la gracia del Espíritu Santo. Pues el Padre es uno, pero las personas son dos…','Contra Noeto 14','Lagarde 1858 p. 52 (capturada en HP20); '+SAL+', p. 556. Lagarde anota la variante «οἰκονομία(ν)»'),
  Q('LAG53','gr','ἄλλως τε ἕνα θεὸν νομίσαι μὴ δυνάμεθα, ἐὰν μὴ ὄντως πατρὶ καὶ υἱῷ καὶ ἁγίῳ πνεύματι πιστεύσωμεν.','Y de otro modo no podemos pensar en un solo Dios, si no creemos de verdad en el Padre, en el Hijo y en el Espíritu Santo.','Contra Noeto 14','Lagarde p. 53, l. 6-7 (capturada en HP20); leído por mí en la imagen; ANF: «we cannot otherwise think of one God, unless we truly believe in Father and Son and Holy Spirit»'),
  Q('H2-09','gr',G('H2-09','λέγων'),'diciendo: «Id y haced discípulos a todas las naciones, bautizándolos en el nombre del Padre, y del Hijo, y del Espíritu Santo», mostrando que todo el que omita uno de éstos no glorifica perfectamente a Dios. Pues por medio de esta tríada (triados) se glorifica al Padre. Pues el Padre quiso, el Hijo hizo, el Espíritu manifestó.','Contra Noeto 14','Lagarde 1858 p. 53; '+SAL+', p. 556')],
 '<b>Qué dice.</b> Un solo Dios, <b>dos personas</b> y una «tercera» (la gracia del Espíritu), la <b>«tríada»</b> (<i>trías</i>) con Mt 28:19, y «el Padre quiso, el Hijo hizo, el Espíritu manifestó». <b>Límite.</b> Hipólito llama al Espíritu «gracia» y «tercera economía», no lo coloca aún como persona de igual orden que el Hijo; y <i>prosopon</i> no es todavía la «persona» de Nicea. Es un testigo <b>trinitario en estructura</b> (Padre, Hijo, Espíritu, «tríada») con lenguaje de «economía», no un trinitario niceno formulado. Un investigador anota dudas de crítica textual sobre Mt 28:19 (no las leí).')

add('HP06', 'Pasaje difícil A (C. Noet. 14): «el Padre manda, el Hijo obedece, el Espíritu da entendimiento»', 'La frase que citan arrianos, unitarios y críticos musulmanes',
 [Q('H2-08','gr',G('H2-08'),'… y luego el tercero, el Espíritu Santo. El Padre ordena, el Verbo ejecuta, y el Hijo se muestra, por quien el Padre es creído. Por economía se reúne la concordia en un solo Dios. Pues Dios es uno. Pues el que manda es el Padre, el que obedece es el Hijo, y el que da entendimiento es el Espíritu Santo. El que es Padre, sobre todos; el Hijo, por todos; y el Espíritu Santo, en todos.','Contra Noeto 14','Lagarde 1858 p. 53; '+SAL+', p. 556'),
  Q('H10-04','en',EN('H10-04', None, 'one God.'),'Bull lo cita y concluye: «Hipólito enseña claramente que el Padre, el Hijo y el Espíritu Santo son un solo Dios».','Bull, Defensio Fidei Nicaenae, p. 216 (trad. 1851)','Inglés: Oxford, J. H. Parker 1851; leído en el texto del PDF (p. 240)')],
 '<b>Por qué es difícil.</b> «Manda… obedece» parece subordinación de naturaleza. <b>Resolución.</b> (1) El propio Hipólito da la razón: <b>«por economía»</b> la diferencia de oficio se reúne «en un solo Dios» («Dios es uno»). (2) Se pasa de «obedece» a una fórmula de presencia: Padre <i>epí pántōn</i> (sobre todos), Hijo <i>diá pántōn</i> (por todos), Espíritu <i>en pâsin</i> (en todos), que Ireneo ya conocía (Haer. 5.18.2) y que Basilio y Gregorio leerán como <b>orden sin desigualdad</b>: aquí lo marco como lectura mía. (3) Aquino (ST I q.27 a.2) explica la generación como procesión «en la misma naturaleza específica», no como orden de menor a mayor (HP17). <b>Límite.</b> Hipólito no dice «de la misma naturaleza»; la lectura nicena es una relectura. Bethune-Baker (p. 109) lista la «subordinación estricta» entre las objeciones, y no la resuelve.')

add('HP07', 'Pasaje difícil B (C. Noet. 15): el Verbo «a quien llamó Hijo por lo que iba a ser»', 'El Hijo, ¿sólo Hijo desde la encarnación?',
 [Q('H2-11','gr',G('H2-11'),'¿Qué hijo suyo, pues, envió Dios por medio de la carne sino el Verbo, a quien llamó Hijo por haber de llegar a serlo? Y el Hijo, llamado así, toma el nombre común del cariño hacia los hombres. Pues ni el Verbo, sin carne y por sí mismo, era Hijo perfecto (aunque Verbo perfecto, unigénito), ni la carne por sí misma, sin el Verbo, podía subsistir, porque tiene su consistencia en el Verbo. Así, pues, se manifestó un solo Hijo perfecto de Dios.','Contra Noeto 15','Lagarde 1858 p. 54; '+SAL+', p. 557'),
  Q('H10-01','en',EN('H10-01'),'Respondo que su sentido era manifiestamente que, antes de la Encarnación, el Verbo no había cumplido, por así decir, toda clase de filiación; o, en otras palabras, no era todavía el Hijo de Dios en todas las maneras en que el Padre quería que lo fuera.','Bull, Defensio Fidei Nicaenae, VIII.2, p. 214','Inglés: Oxford 1851; leído en el PDF (p. 238)'),
  Q('H10-06','en',EN('H10-06'),'Era el Verbo perfecto, unigénito del Padre, pero todavía no el Hijo perfecto: esto lo llegó a ser cuando se hizo hombre.','Bethune-Baker, Introduction to the Early History of Christian Doctrine, p. 108','Inglés: Methuen 1903; resumen de Döllinger, no cita directa de Hipólito')],
 '<b>Por qué es difícil.</b> «Hijo por lo que iba a ser» y «el Verbo… no era Hijo perfecto antes de la carne» hacen la filiación <b>económica o encarnatoria</b>: lo más duro de <i>Contra Noeto</i>. <b>Resolución (Bull).</b> «Unigénito» ya se aplica al Verbo antes de la carne (el mismo texto); la plenitud de filiación es la del Hijo encarnado, «una sola filiación perfecta» que une Verbo y carne. <b>Límite honesto.</b> Bethune-Baker y Döllinger leen un Hipólito para quien el Verbo «llegó a ser Hijo» al hacerse hombre; la nota editorial de Robertson (NPNF2 vol. 4, p. 347, en Atanasio) cita este mismo pasaje como ejemplo del lenguaje que los arrianos aprovechaban y resume a estos autores como enseñando el Verbo «desde la eternidad» pero Hijo «al comienzo de todas las cosas»; es lectura del editor, no de Atanasio. Es el pasaje que más se resuelve por <b>relectura posterior</b> (HP17).')

add('HP08', 'Pasaje difícil C (Ref. 10.32-33): «engendró el Verbo… de lo que existe», «mente interior» y luego «hijo»', 'El Verbo «concebido» y luego «engendrado» para crear',
 [Q('H2-13','gr',G('H2-13'),'Pero me dirás: ¿cómo ha sido engendrado? Tu propia manera de haber sido engendrado no puedes explicarla, aunque ves cada día la causa humana, y la economía de esto no puedes exponerla con exactitud. Pues no está en tu mano conocer el arte experto e inenarrable del Creador, sino sólo, viéndolo, entender y creer que el hombre es obra de Dios. Y buscas la generación del Verbo, al que Dios Padre, queriendo, engendró como quiso.','Contra Noeto 16','Lagarde 1858 p. 54-55 (la p. 54 está capturada en HP21); '+SAL+', p. 558'),
  Q('H4-02','gr',G('H4-02'),'Éste, pues, solo y sobre todo, Dios, concibiendo, engendra primero el Verbo; no un verbo como voz, sino el razonamiento interior (endiathetos) del todo. A éste solo lo engendró de lo que existe: pues el ser era el Padre mismo, de quien el ser engendrado es causa de lo que se hace.','Refutación X.33','Miller 1851 p. 334-335; '+MAC+'. '+MIL)],
 '<b>Por qué es difícil.</b> «Engendró como quiso» (C. Noet. 16) y «concibiendo, engendra primero el Verbo» y «de lo que existe» (<i>ex ontōn</i>) son los términos que el arriano lee como producción de un ser, y la «mente interior» (<i>endiáthetos</i>) como una tierra de nadie entre Padre e Hijo. <b>Resolución.</b> (1) Hipólito mismo rechaza la pregunta «¿cómo?»: igual que Ireneo (2.28.6, IR06), dice que <b>el modo no se puede explicar</b>; en el cap. 16 cita Sal 110:3 LXX («del seno, antes del lucero, te engendré») y Jn 3:6 y declara que el hecho es cierto y el modo, reservado (H2-14). (2) Atanasio (Or. contra los arrianos 2.57): «no comenzó a ser… sino que era siempre»; la criatura es «de fuera», lo engendrado es «de la esencia». Aquino (ST I q.34 a.1-2): el Verbo en Dios es nombre <b>personal</b> y «substancial». <b>Límite.</b> Hipólito mezcla ahí el esquema de «prolación» (Verbo interior, luego exteriorizado) con la generación; Hipólito no distingue entre generación eterna y generación «para crear»; esa distinción llega en el siglo IV (Newman, <i>Arians</i>, p. 215, recoge el reproche de que estos Padres admitían una «prolación»). El Verbo es «engendrado antes de todo» (<i>Cristo y Anticristo</i> 26) pero no «eternamente»: la eternidad la añade Nicea.')

add('HP09', 'Ref. 10.33: «el Verbo es Dios, siendo la sustancia de Dios»; «Cristo es el Dios sobre todo»', 'Lo más fuerte del lado trinitario',
 [Q('H4-08','gr',G('H4-08'),'De éste el Verbo es solo de él mismo: por eso también Dios, siendo sustancia (ousia) de Dios. Pero el mundo, de nada: por eso no Dios; éste admite también disolución cuando lo quiere el que lo creó.','Refutación X.33','Miller 1851 p. 336 (capturada en HP22); '+MAC+'. '+MIL),
  Q('H4-10','gr',G('H4-10', None, 'λέγων,'),'A este Verbo lo envió el Padre en los últimos tiempos, no ya para hablar por medio de un profeta, ni queriendo que fuese tenido sólo por sospecha, predicado oscuramente, sino diciendo que se manifestara cara a cara…','Refutación X.33','Miller 1851 p. 337; '+MAC),
  Q('H4-13','gr',G('H4-13', 'Χριστὸς γάρ', 'ἄνθρωπον,') if False else G('H4-13'),'No os llenéis, pues, de enemistad unos con otros, hombres, ni dudéis en volver atrás: pues Cristo es el Dios sobre todo (ho katà pántōn Theós), que mandó lavar el pecado de los hombres, renovando al hombre viejo…','Refutación X.34','Miller 1851 p. 339; '+MAC)],
 '<b>Qué dice.</b> «El Verbo es Dios, siendo la <i>ousía</i> de Dios» y «Cristo es el Dios sobre todo»: las frases más cercanas a la divinidad del Hijo y a la «misma sustancia» en Hipólito (el investigador H4 las marcó VERIFIED en la imagen). <b>Límites que debo decir.</b> (1) <i>theós</i> sin artículo («Dios» o «divino») es la lectura que opone el arriano; (2) «de éste el Verbo es solo de él mismo» (<i>ex autoû</i>) puede decir <i>origen</i>; (3) «enviar» es lenguaje de misión: la subordinación de oficio, no de naturaleza (HP06); (4) «Dios sobre todo» se dice también del Padre (Ef 4:6, Rom 9:5). Mi lectura: 10.33 es, de las obras que verifiqué, <b>el texto de Hipólito más favorable a la consustancialidad</b>, pero no usa «homoousios».')

add('HP10', 'Pasaje difícil D (Ref. 10.34): «te has hecho Dios… deificado, engendrado para la inmortalidad»', 'La «deificación» no es un «Dios hecho» de la creatura',
 [Q('MIL336','gr','Εἰ γὰρ θεόν σε ἠθέλησε ποιῆσαι, ἐδύνατο· ἔχεις τοῦ Λόγου τὸ παράδειγμα· ἄνθρωπον θέλων, ἄνθρωπόν σε ἐποίησεν· εἰ δὲ θέλεις καὶ θεὸς γενέσθαι, ὑπάκουε τῷ πεποιηκότι, καὶ μὴ ἀντίβαινε νῦν, ἵνα ἐπὶ τῷ μικρῷ πιστὸς εὑρεθεὶς, καὶ τὸ μέγα πιστευθῆναι δυνηθῇς.','Pues si hubiera querido hacerte Dios, podía; tienes el modelo en el Verbo; queriendo un hombre, te hizo hombre. Pero si quieres llegar a ser también Dios, obedece al que te hizo, y no te resistas ahora, para que, hallado fiel en lo pequeño, puedas también recibir la confianza en lo grande.','Refutación X.33','Miller 1851 p. 336, l. 1-6 (capturada en HP22); leído por mí en la imagen; '+MAC+', p. 151'),
  Q('H4-12','gr',G('H4-12'),'Pues te has hecho Dios: pues cuanto padeciste siendo hombre, esto te lo dio por ser de condición mortal; pero cuanto conviene a Dios, esto te prometió concederlo Dios, cuando seas deificado (theopoiēthēs), engendrado para la inmortalidad.','Refutación X.34','Miller 1851 p. 339; '+MAC+'. '+MIL)],
 '<b>Por qué es difícil.</b> «Te has hecho Dios» lo citan unitarios y críticos musulmanes como prueba de que «ser Dios» se predica de cualquiera, y que no distingue al Hijo. <b>Resolución.</b> (1) El texto mismo pone la deificación como <b>don futuro</b> («cuando seas deificado»; «te prometió concederlo»). (2) El mismo pasaje, un párrafo antes (10.33, que vi yo en la página), dice que si Dios hubiera querido hacerte Dios, «podía», pero te hizo hombre: tienes <b>el modelo en el Verbo</b>, y sólo si «obedeces al que te hizo» puedes llegar a ser «también Dios». Es participación («cuanto conviene a Dios, esto te lo concederá»), no igualdad de naturaleza: en 10.33 Hipólito dice del Verbo que es «de la sustancia» de Dios y del mundo y del hombre que son «de nada». (3) El texto dice <i>theós</i> sin artículo y no llama al hombre «Dios sobre todo», título que sí da a Cristo en 10.34. <b>Límite.</b> No leí nada de Atanasio sobre este pasaje: mi lectura es la del propio texto. Es un uso, además, ligado a la teología de la salvación, no a la doctrina de la Trinidad.')

add('HP11', 'Pasaje difícil E (Ref. 9.11-12): Calixto lo llama «ditheísta»; Hipólito atribuye a Calixto un solo sujeto', 'La acusación de «dos dioses» y el término «prosopon»',
 [Q('H3-10','gr',G('H3-10'),'… pero a nosotros no: nos llamaba «dos-dioses» (ditheous), vomitando por la fuerza el veneno que se esconde en su interior.','Refutación IX.11','Duncker-Schneidewin p. 452; '+MAC+'. '+DUN),
  Q('H3-12','gr',G('H3-12'),'… diciendo que el Verbo mismo es el Hijo, y él mismo también Padre, llamado con nombre diferente, pero siendo un solo espíritu indivisible; que no es el Padre uno y el Hijo otro, sino uno y lo mismo.','Refutación IX.12','Duncker-Schneidewin p. 458 (capturada en HP22); '+MAC+'. '+DUN),
  Q('H3-13','gr',G('H3-13'),'… y que, siendo esto una sola persona (prosopon), no puede ser dos, y así el Padre habría padecido con el Hijo.','Refutación IX.12','Duncker-Schneidewin p. 458 (capturada en HP22); '+MAC+'. '+DUN)],
 '<b>Qué muestra.</b> Calixto reprocha a Hipólito ser «ditheísta»; Hipólito responde presentando a Calixto como modalista («un solo prosopon, indivisible»; el Padre «padeció con el Hijo»). Aquí <i>prosopon</i> es «un sujeto/persona única»: <b>el mismo término que Hipólito usa para «dos personas» en C. Noet. 7 y 14</b>. <b>Límite.</b> Los tres textos son <b>informes de Hipólito sobre sus adversarios</b>; no son doctrina propia, y ninguno apoya por sí solo una lectura trinitaria (H3 lo advirtió). Sirven para mostrar que Hipólito <b>distinguía a Padre e Hijo</b> y que su propio círculo fue acusado de «dos dioses», lo que Bethune-Baker (p. 108) recuerda como una acusación de ditheísmo contra Hipólito, sin decidir si era justa.')

add('HP12', 'Otras obras: «Verbo engendrado del corazón del Padre antes de todo» y el cuarto del horno', 'Cristo y Anticristo 26; Comentario a Daniel (Dan 3 y 7)',
 [Q('H5-04','gr',G('H5-04'),'… mostró todo el poder que el Padre había dado al Hijo, quien ha sido declarado rey y juez de todo, de lo celestial, lo terrestre y lo subterráneo: de lo celestial, porque es el Verbo engendrado del corazón del Padre antes de todo.','Cristo y Anticristo 26','Griego: GCS 1 (OCR, leído por un investigador); '+'Inglés: ANF vol. 5, p. 209 (omite «del corazón del Padre»)'),
  Q('H5-06','gr',G('H5-06', 'καὶ ἡ ὅρασις', 'ἐν τῇ καμίνῳ δοξάσῃ'),'«Y la visión del cuarto es semejante a un hijo de Dios». Dime, Nabucodonosor, ¿cuándo viste al Hijo de Dios, para confesar que éste es hijo de Dios? ¿Y quién traspasó tu corazón, para que pronunciases tal palabra? […] La mano de Dios, que era el Verbo, traspasó el corazón de éste, para que, reconociéndolo, lo glorificara en el horno.','Comentario a Daniel (Dan 3:92 LXX)','Griego: GCS (OCR) p. 106; '+SAL+'; New Advent'),
  Q('H5-08','gr',G('H5-08'),'… Dios encarnado y hombre, Hijo de Dios e Hijo del hombre.','Comentario a Daniel (Dan 7:13-14)','Griego: GCS; '+SAL+'; página no confirmada')],
 '<b>Qué dicen.</b> El Verbo «engendrado del corazón del Padre antes de todo»; el Hijo ya «visto» en el horno como Verbo («mano de Dios»); «Dios encarnado y hombre». <b>Límites.</b> (1) «Antes de todo» no es «sin principio»; (2) la «mano de Dios» como el Verbo es un uso de «manos» emparentado con Ireneo (4.20.1) pero de aplicación al Verbo solo; (3) el investigador H5 no resolvió si el «Cristo es Dios» de <i>Cristo y Anticristo</i> 6 está en el griego, así que <b>no lo cito</b>; (4) <i>In Cantica</i>, <i>De Pascha</i> y el Daniel eslavo no se leyeron; (5) los números de página ANF son aproximados.')

add('HP13', 'Textos dudosos, espurios o tardíos: no valen como prueba de Hipólito', 'Tradición apostólica, Contra Beron y Helix, pseudo-Hipólito',
 [Q('H6-05','en',EN('H6-05'),'Creo en el único Dios verdadero, el Padre, omnipotente, y en su único Hijo Jesucristo, Señor y Salvador nuestro, y en su Espíritu Santo, vivificador del universo, la Trinidad de la misma sustancia (trias en homoousion), una divinidad, un señorío, un reino…','Statutes of the Apostles (versión sahídica), Horner 1904, p. 317','Inglés: Horner 1904; leído en el PDF (p. 364); texto tardío: tiene «homoousion»'),
  Q('H6-06','en',EN('H6-06'),'Por último, en árabe se conservan los Cánones de Hipólito y las Constituciones de Hipólito, cuyo nombre se halla además en el etíope, probablemente derivado del árabe. En qué medida se acepta la autoría de Hipólito no se puede determinar por ahora…','Horner 1904, Introducción, p. viii','Inglés: Horner; PDF p. 13'),
  Q('H7-02','en',EN('H7-02'),'«…si las naturalezas se funden, Cristo será una dualidad; y si las personas se separan, habrá una cuaternidad (tetras), cosa sumamente de evitar.» (El traductor glosa «en lugar de Trinidad»).','Contra Beron y Helix, fragmento V','Griego: Lagarde 1858 p. 61-62 (OCR); '+SAL+'. «Trinidad» es glosa de la ANF, no del griego')],
 '<b>Por qué no cuentan.</b> La <i>Tradición apostólica</i> (con su interrogatorio bautismal «¿Crees en Dios Padre omnipotente… en Cristo Jesús, el Hijo de Dios… en el Espíritu Santo?») se conserva sólo en latín, copto, etíope, árabe y siríaco, <b>no en el griego original</b>, y su atribución a Hipólito es discutida (Horner, p. viii; Achelis; Brent; no leí a Brent ni a Bradshaw). La versión sahídica con «trias en homoousion» es <b>una recensión tardía</b>, no Hipólito. El fragmento <i>Contra Beron</i> usa «tetras», no «trias» (la «Trinidad» es de la traducción). Los «Cánones de Alejandría» y el discurso <i>Sobre el fin del mundo</i> («sin principio como el Padre y coeterno con el Espíritu») son espurios o dudosos (ANF). <b>No uso ninguno como testimonio</b> del propio Hipólito.')

add('HP14', 'Lo que Hipólito NO dice, y correcciones al material de partida', 'Para no atribuirle lo que no es suyo', [],
 '<ul class="l" style="font-size:15.5px;line-height:1.5"><li><b>No dice «homoousios» ni «Trinidad (trinitas)».</b> Usa «tría», «tríada» (<i>trías</i>, C. Noet. 14) y «un solo poder». El «Trinity» de <i>Contra Beron</i> es glosa del traductor.</li><li><b>No dice que el Espíritu sea persona de igual orden que el Hijo.</b> Es «la gracia», «la tercera economía», el que «da entendimiento»; la lista «Padre, Hijo y Espíritu» está en C. Noet. 8 y 14.</li><li><b>La frase «el Padre manda y el Hijo obedece» es de C. Noet. 14</b> (no de 12-13); «dos personas» ya aparece en el capítulo 7.</li><li><b>«Cuando quiso creó el mundo» no aparece con esas palabras</b> en Ref. 10.33: lo más cercano es «cuando quiso, también hizo». <b>«Serás un dios»</b> tampoco: los textos reales son «si quieres ser también Dios» (10.33) y «te has hecho Dios» (10.34).</li><li><b>El pasaje «el Verbo es Dios, siendo la sustancia de Dios»</b> es de Ref. <b>X.33</b>, no de X.32.</li><li><b>El traductor de <i>Contra Noeto</i> en ANF vol. 5 es Salmond</b> (la <i>Refutación</i> es de MacMahon); un investigador lo atribuyó a MacMahon: está en la sección de «Extant Works» traducida por Salmond.</li><li><b>«Contra Noeto» termina en el cap. 18</b> con una doxología; no hay una «conclusión/refutación» separada en Lagarde ni en ANF.</li><li><b>El pasaje del horno es Dan 3 (LXX 3:92-93)</b>, no «4.11».</li><li><b>Eusebio no nombra «Contra Noeto» ni la Refutación</b> en su lista (HE 6.22.2), ni Jerónimo (De vir. ill. 61).</li><li><b>Los «escritos griegos» a veces atribuidos</b> (Contra los griegos, Homilía de Pascua, Contra Platón) no se verificaron como suyos; «Contra Platón» es sobre el Hades, sin Trinidad.</li></ul>')

add('HP15', 'Lo que dicen los estudiosos (1): a favor de una estructura trinitaria', 'Bull, Newman, Harnack (economía)',
 [Q('H10-08','en',EN('H10-08'),'Así dice Hipólito: «Cuando digo que el Hijo es distinto del Padre, no hablo de dos Dioses, sino, por así decir, de luz de luz, de arroyo de la fuente y de rayo del sol».','Newman, Arians of the Fourth Century, p. 195','Inglés: Newman, trad. propia (1833/1890); leído en el PDF'),
  Q('H10-04','en',EN('H10-04', 'Here, as you see'),'Aquí, como ves, Hipólito enseña claramente que el Padre, el Hijo y el Espíritu Santo son un solo Dios.','Bull, Defensio Fidei Nicaenae, p. 216','Inglés: Oxford 1851'),
  Q('H10-15','en',EN('H10-15'),'Tertuliano e Hipólito limitan la economía de Dios al Padre, al Hijo y al Espíritu Santo, mientras que los gnósticos exceden este número.','Harnack, History of Dogma vol. 2, p. 258','Inglés: Buchanan; leído en el PDF (p. 278)')],
 '<b>Quién lo dice.</b> Bull (1685, trad. 1851) y Newman leen a Hipólito como defensor de un solo Dios con tres. Harnack reconoce que limita la economía a tres. <b>Límite.</b> Bull es un apologista niceno del siglo XVII, no un lector neutral; Newman lo es del XIX y reconoce que las imágenes «luz de luz» admiten mala lectura. Yo no pude abrir Kelly, Prestige, Hanson, Simonetti, Quasten, Nautin, Wolfson, Brent, Cerrato ni Butterworth: lo que escribo de ellos viene de lo que otros citan, no de su texto.')

add('HP16', 'Lo que dicen los estudiosos (2): las objeciones', 'Harnack, Bethune-Baker, Döllinger',
 [Q('H10-13','en',EN('H10-13'),'Tertuliano e Hipólito saben tan poco de una Trinidad inmanente como los Apologistas; la Trinidad sólo lo parece porque se subraya con fuerza la unidad de la sustancia; pero en verdad el proceso trinitario es, como entre los gnósticos, simplemente el trasfondo del proceso que produce la historia del mundo y de la salvación.','Harnack, History of Dogma vol. 2, pp. 260-261','Inglés: Buchanan; leído en el PDF (pp. 280-281)'),
  Q('H10-05','en',EN('H10-05'),'Su propia teología [la de Hipólito] causó casi igual escándalo y fue acusada de ditheísmo.','Bethune-Baker, Introduction, p. 108','Inglés: Methuen 1903'),
  Q('H10-07','en',EN('H10-07'),'(2) subordinación estricta: el Hijo es meramente una fuerza que ejecuta las órdenes del Padre;','Bethune-Baker, Introduction, p. 109','Inglés: Methuen 1903')],
 '<b>Quién lo dice.</b> Harnack niega que Hipólito tenga una Trinidad <b>inmanente</b>: para él las tres «personas» son sobre todo economía de la historia. Bethune-Baker recoge la acusación antigua de «ditheísmo» y lista la «subordinación estricta» como objeción. <b>Resolución honesta.</b> Estas objeciones no se refutan con un «texto»: se responden mostrando que (a) el propio Hipólito afirma «Dios es uno» y «los tres» (HP03, HP05), (b) las frases de misión y orden son de <b>oficio</b> (HP06), (c) el Verbo «es de la sustancia de Dios» (HP09), y (d) la plenitud de filiación (HP07) y la generación «para crear» (HP08) quedan <b>abiertas</b> hasta Nicea. Lo que no puedo afirmar es que Hipólito pensara una Trinidad inmanente: lo que muestran los textos es una economía de tres con un fondo ontológico (poder, sustancia) todavía sin formular.')

add('HP17', 'Cómo lo resuelve la teología posterior (1): generación, Verbo y subordinación', 'Atanasio, Agustín, Aquino',
 [Q('H11-13','en',EN('H11-13'),'Pues si hubiera sido una criatura, no habría dicho «me engendra», porque las criaturas son de fuera y obras del Hacedor; pero lo engendrado no es de fuera ni obra, sino del Padre y propio de su esencia. […] Por tanto, las criaturas comenzaron a ser hechas; pero el Verbo de Dios, no teniendo comienzo de ser, ciertamente no comenzó a ser, sino que era siempre.','Atanasio, Contra los arrianos 2.57','Inglés: Newman y Robertson, NPNF2 vol. 4'),
  Q('H11-31','en',EN('H11-31'),'La procesión del Verbo en Dios se llama generación. […] la generación incluye… una procesión por vía de semejanza en la misma naturaleza específica, como un hombre procede de un hombre.','Aquino, Suma teológica I q.27 a.2','Inglés: Padres Dominicos ingleses'),
  Q('H11-32','en',EN('H11-32'),'El nombre de Verbo en Dios, tomado en su sentido propio, es un nombre personal y de ningún modo esencial.','Aquino, Suma teológica I q.34 a.1','Inglés: Padres Dominicos ingleses'),
  Q('H11-28','en',EN('H11-28', 'The Word of God'),'El Verbo de Dios, Hijo unigénito del Padre, en todo semejante e igual al Padre, Dios de Dios, Luz de Luz, Sabiduría de Sabiduría, Esencia de Esencia, es del todo lo que es el Padre, sin ser el Padre, porque uno es Hijo y otro es Padre.','Agustín, De Trinitate XV.14.23','Inglés: Haddan, NPNF1 vol. 3')],
 '<b>Aplicación a Hipólito (mía).</b> Los esquemas «concebir y luego engendrar» (Ref. 10.33) y «luz de luz» (C. Noet. 11) son los que Atanasio y Agustín <b>reinterpretan</b>: el Verbo «era siempre» (Atanasio) y es «Dios de Dios, luz de luz… esencia de esencia» (Agustín). Aquino distingue el Verbo <b>personal</b> y <b>substancial</b> del «verbo» de una criatura. <b>Límite.</b> Atanasio no nombra a Hipólito en el texto de NPNF2 que leí; sólo las notas editoriales de Robertson (p. 347) lo mencionan. «Dios de Dios, luz de luz» es de Agustín; <b>no encontré el texto del Credo Niceno</b> en las fuentes que leí, de modo que no lo cito.')

add('HP18', 'Cómo lo resuelve la teología posterior (2): «tres personas, una esencia»', 'Tertuliano, Novatian, Basilio, Gregorio de Nacianzo',
 [Q('H11-19','en',EN('H11-19'),'El misterio de la economía… distribuye la Unidad en Trinidad, colocando en su orden las tres personas: Padre, Hijo y Espíritu Santo; tres, pero no en condición sino en grado, no en sustancia sino en forma, no en poder sino en aspecto; de una sola sustancia, una sola condición y un solo poder.','Tertuliano, Adversus Praxean 2','Inglés: Holmes, ANF vol. 3'),
  Q('H11-23','en',EN('H11-23'),'Estos Tres son una esencia, no una persona, como se dice «yo y el Padre somos uno», por la unidad de sustancia, no por la singularidad de número.','Tertuliano, Adversus Praxean 25','Inglés: Holmes, ANF vol. 3'),
  Q('H11-26','en',EN('H11-26'),'La distinción entre <i>ousía</i> e <i>hypóstasis</i> es la misma que entre lo general y lo particular… Por eso, en el caso de la Divinidad, confesamos una esencia o sustancia, pero confesamos una hipóstasis particular.','Basilio, Carta 236, 6','Inglés: Jackson, NPNF2 vol. 8'),
  Q('H11-27','en',EN('H11-27'),'Cuando miramos la Divinidad, o la Causa primera, o la Monarquía, lo que concebimos es Uno; pero cuando miramos las Personas en quienes habita la Divinidad… son Tres los que adoramos.','Gregorio Nacianceno, Or. 31.14','Inglés: Browne y Swallow, NPNF2 vol. 7')],
 '<b>Aplicación a Hipólito (mía).</b> Su «un solo poder, dos personas, una tercera» (C. Noet. 7 y 14) es lo que <b>Tertuliano formula con «sustancia»</b> pocos años antes (<i>Adv. Prax.</i> 2 y 25: «tres… de una sustancia») y lo que Basilio y Gregorio terminan con «<i>ousía</i> una, <i>hypóstasis</i> tres». <b>Límite.</b> Hipólito no usa ninguna de esas distinciones: dice «poder» y «economía». Lo propiamente niceno del lenguaje es posterior; lo verificable de Hipólito es la estructura «Dios uno, tres, un solo poder». No hallé en Hipólito un texto equivalente a «consustancial» (el «homoousion» sahídico de HP13 es tardío).')

add('HP19', 'Resumen de pasajes difíciles y cómo se resuelven', 'Veredicto honesto: trinitario en estructura («un solo Dios, tres, un solo poder»), con lenguaje de «economía», no un trinitario niceno', [], '__TABLE__')
